// Import of required libraries
import { test, expect, getBaseUrl, newSkyrampPlaywrightPage } from '@skyramp/skyramp';
import { openOwnersSearchList, findOwnerByLastName, openOwnerDetail } from './skyrampUtils';

const pageTimeout = 15000;

// URL for test requests
const baseUrl = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:4200");

test.use({
    viewport: { width: 1280, height: 900 },
});

test('testUi', async ({ page }) => {
    test.setTimeout(60000);

    // set default timeout for all locator/page actions in this test
    page.setDefaultTimeout(pageTimeout);
    // Wrap playwright page with Skyramp page
    page = newSkyrampPlaywrightPage(page);

    await page.goto(baseUrl);
    await openOwnersSearchList(page);
    await findOwnerByLastName(page, "Davis");

    // The last-name filter must narrow the list to the matching owners only.
    await expect(page.getByRole("link", { name: "Betty Davis" })).toBeVisible();
    await expect(page.getByRole("link", { name: "George Franklin" })).toHaveCount(0);

    await openOwnerDetail(page, "/petclinic/owners/2");

    await expect(page).toHaveURL(`${baseUrl}/petclinic/owners/2`);
    await expect(page.locator(".ownerFullName")).toHaveText("Betty Davis");

    // Betty Davis' pet "Basil" carries no nickname, so pet-list.component.html
    // must still render the pet row and its Nickname label with an empty value
    // rather than dropping the pet from the list.
    await expect(page.locator("main")).toContainText("Basil");
    await expect(page.locator("main")).toContainText("Nickname");
});
